from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class GPSStatusInterface(BaseClToolInterface):

    def get_gps_status(self, timeout='15min', **kwargs):
        """Gets GPS status from one site.

        kwarg values for Get GPS Status
        check_for_errors - boolean - set to False to ignore raised exception if there is not GPS

        :return Path(s) of collected file(s).
        :rtype list

        :note: Fetches either GPS related alarms or detailed GPS information if no alarms found.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        check_for_errors = kwargs.get('check_for_errors', True)
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='getgpsstatus',
                                               params=params, trs_ip=ne, flags=flags, symlink='conf', check_for_errors=check_for_errors)
